} from "../types/view";
import {
  applyLayerTransform,
  applyLayerTransforms,
  createDataLayer,
  createEntity,
  createView,
  createViewPage,
  createViewPageGroup,
  duplicateEntity,
  duplicateSection,
  findMatchingPoint,
  formatYValue,
  isChartEntity,
  isChartLayerEvent,
  isChartLayerLine,
  isDownlinkDashboardEntity,
  isMapEntity,
  isTableEntity,
  isTextEntity,
  isTimelineRowEntity,
} from "./view";

const chartLayer1 = generateTestChartLayer();
const chartLayer2 = generateTestChartLayer();
const chartLayer3 = generateTestChartLayer();
const dummyPoint = generateTestDataEntry();
const testData = [
  {
    layer: chartLayer1,
    pointsByField: {
      field1: [
        {
          x: "2030-01-01T00:00:00.000Z",
          y: 0,
          raw: dummyPoint,
          selected: false,
        },
        {
          x: "2030-01-02T00:00:00.000Z",
          y: 1,
          raw: dummyPoint,
          selected: false,
        },
        {
          x: "2030-01-03T00:00:00.000Z",
          y: 2,
          raw: dummyPoint,
          selected: false,
        },
      ],
    },
  },
  {
    layer: chartLayer2,
