  expect(isDownlinkDashboardEntity(downlink)).toBe(true);
  expect(isDownlinkDashboardEntity(chart)).toBe(false);
  expect(isTimelineRowEntity(timelineRow)).toBe(true);
  expect(isTimelineRowEntity(chart)).toBe(false);
